const PlaywrightWrapper = require("../Framework/src/helper/wrapper/PlaywrightWrappers");

class ProductDetailPage {
    constructor(page, logger) {
        this.page = page;
        this.logger = logger;
        this.base = new PlaywrightWrapper(page, logger);
        this.Elements = {
            productName: ".inventory_details_name",
            productDescription: ".inventory_details_desc",
            productPrice: ".inventory_details_price",
            addToCartButton: "[data-test='add-to-cart']",
            backToProductsButton: "[data-test='back-to-products']",
            cartBadge: ".shopping_cart_badge"
        };
    }

    async getProductName() {
        return this.base.textContent(this.Elements.productName);
    }

    async isAddToCartVisible() {
        return this.base.isVisible(this.Elements.addToCartButton);
    }

    async clickAddToCart() {
        await this.base.waitAndClick(this.Elements.addToCartButton, "Add to Cart Button (Product Detail)");
    }

    async clickBackToProducts() {
        await this.base.waitAndClick(this.Elements.backToProductsButton, "Back to Products Button");
    }

    async getCartBadgeCount() {
        const visible = await this.base.isVisible(this.Elements.cartBadge);
        if (!visible) return 0;
        return parseInt(await this.base.textContent(this.Elements.cartBadge), 10);
    }
}

module.exports = ProductDetailPage;
